import React, { useMemo } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

export type AssuranceClauseStep = {
  id: string;
  label: string;
  description?: string;
  status?: string;
  source?: string;
};

export type AssuranceClauseWorkflow = {
  framework: string;
  clauseId: string;
  clauseRef: string;
  title: string;
  assuranceLevel?: string;
  artifactType?: string;
  status: string;
  required?: boolean;
  agentNote?: string | null;
  steps?: AssuranceClauseStep[];
};

export type AssuranceClauseWorkflowBundle = {
  generatedAt?: string;
  framework?: string;
  workflows?: AssuranceClauseWorkflow[];
  summary?: {
    totalClauses?: number;
    completeCount?: number;
    gapCount?: number;
    inProgressCount?: number;
    readinessScore?: number | null;
  };
};

type AssuranceClauseWorkflowPanelProps = {
  bundle?: AssuranceClauseWorkflowBundle | null;
  frameworkFilter?: 'all' | 'iso14064' | 'brsr';
  title?: string;
};

const statusColor = (status?: string): 'success' | 'warning' | 'error' | 'default' => {
  if (status === 'complete') return 'success';
  if (status === 'gap') return 'error';
  if (status === 'in_progress') return 'warning';
  return 'default';
};

const statusLabel = (status?: string): string => {
  if (status === 'complete') return 'Ready';
  if (status === 'gap') return 'Gap';
  if (status === 'in_progress') return 'In progress';
  return status || 'Pending';
};

const AssuranceClauseWorkflowPanel: React.FC<AssuranceClauseWorkflowPanelProps> = ({
  bundle,
  frameworkFilter = 'all',
  title = 'Clause-level assurance workflows',
}) => {
  const workflows = useMemo(() => {
    const all = bundle?.workflows || [];
    if (frameworkFilter === 'all') {
      return all;
    }
    if (frameworkFilter === 'iso14064') {
      return all.filter((entry) => entry.framework === 'iso14064');
    }
    return all.filter((entry) => entry.framework === 'brsr');
  }, [bundle?.workflows, frameworkFilter]);

  if (!bundle?.workflows?.length) {
    return (
      <Alert severity="info">
        Clause-level assurance workflows will appear after your inventory and disclosure data are loaded.
      </Alert>
    );
  }

  const score = bundle.summary?.readinessScore;

  return (
    <Stack spacing={2}>
      <Box>
        <Typography variant="subtitle1" fontWeight={600} gutterBottom>
          {title}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          Step-by-step checkpoints mapped to ISO 14064 and BRSR Principle 6 clause references for limited assurance prep.
        </Typography>
        {score != null ? (
          <Stack direction="row" alignItems="center" spacing={2}>
            <Typography variant="h5">{score}%</Typography>
            <Box sx={{ flex: 1 }}>
              <LinearProgress variant="determinate" value={Math.min(100, score)} sx={{ height: 8, borderRadius: 1 }} />
            </Box>
            <Typography variant="caption" color="text.secondary">
              {bundle.summary?.completeCount ?? 0}/{bundle.summary?.totalClauses ?? workflows.length} clauses ready
            </Typography>
          </Stack>
        ) : null}
      </Box>

      {workflows.map((workflow) => (
        <Accordion key={`${workflow.framework}-${workflow.clauseId}`} variant="outlined" disableGutters>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" sx={{ width: '100%', pr: 1 }}>
              <Chip size="small" label={statusLabel(workflow.status)} color={statusColor(workflow.status)} />
              <Typography variant="body2" fontWeight={600}>
                {workflow.clauseRef}
              </Typography>
              {workflow.assuranceLevel ? (
                <Chip size="small" variant="outlined" label={`${workflow.assuranceLevel} assurance`} />
              ) : null}
            </Stack>
          </AccordionSummary>
          <AccordionDetails>
            <Typography variant="body2" sx={{ mb: 1 }}>
              {workflow.title}
            </Typography>
            {workflow.agentNote ? (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                {workflow.agentNote}
              </Typography>
            ) : null}
            <Stack spacing={1}>
              {(workflow.steps || []).map((step) => (
                <Stack key={step.id} direction="row" spacing={1} alignItems="flex-start">
                  <Chip size="small" label={statusLabel(step.status)} color={statusColor(step.status)} variant="outlined" />
                  <Box>
                    <Typography variant="body2">{step.label}</Typography>
                    {step.description ? (
                      <Typography variant="caption" color="text.secondary">
                        {step.description}
                      </Typography>
                    ) : null}
                  </Box>
                </Stack>
              ))}
            </Stack>
          </AccordionDetails>
        </Accordion>
      ))}
    </Stack>
  );
};

export default AssuranceClauseWorkflowPanel;
